    "setup_time_minutes": 60,
    "teardown_time_minutes": 30,
    "security_deposit_minor": 50000,
    "minimum_space_sqm": 25
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

